parameters.jsCode:
const request = $('Normalize Action').first().json;
const response = $input.first().json;

const statusCode = response.statusCode == null
  ? NaN
  : Number(response.statusCode);

const body = response.body;

function fail(httpStatus, error, message) {
  return [{
    json: {
      accepted: false,
      schema_version: "1.0",
      request_id: request.request_id,
      incident_id: request.incident_id,
      astronaut_id: request.astronaut_id,
      error,
      message,
      http_status: httpStatus
    }
  }];
}

// Handle backend HTTP errors
if (!Number.isInteger(statusCode) || statusCode < 100 || statusCode > 599) {
  return fail(
    502,
    "INVALID_BACKEND_RESPONSE",
    "The backend returned an invalid response."
  );
}

if (statusCode === 404) {
  return fail(
    404,
    "INCIDENT_NOT_FOUND",
    "The requested incident was not found."
  );
}

if (statusCode === 409) {
  return fail(
    409,
    "REVIEW_ACTION_CONFLICT",
    "The action conflicts with the incident state or request ID. Check the incident and action history before retrying."
  );
}

if (statusCode === 401 || statusCode === 403) {
  return fail(
    403,
    "REVIEW_ACTION_FORBIDDEN",
    "The review action is not authorized."
  );
}

if (statusCode === 400 || statusCode === 422) {
  return fail(
    400,
    "BACKEND_VALIDATION_ERROR",
    "The backend rejected the review request."
  );
}

if (statusCode === 429 || statusCode >= 500) {
  return fail(
    503,
    "BACKEND_UNAVAILABLE",
    "The incident update could not be confirmed. Check the incident status before retrying with the same request_id."
  );
}

if (statusCode < 200 || statusCode >= 300) {
  return fail(
    502,
    "UNEXPECTED_BACKEND_RESPONSE",
    "The backend returned an unexpected response."
  );
}

// Validate response structure
if (!body || typeof body !== "object" || Array.isArray(body)) {
  return fail(
    502,
    "INVALID_RESPONSE_BODY",
    "The backend response could not be validated."
  );
}

// Verify backend reported success
if (body.success !== true) {
  return fail(
    502,
    "BACKEND_ACTION_FAILED",
    "The backend did not confirm successful action execution."
  );
}

// Verify incident and astronaut identity
if (
  body.incident_id !== request.incident_id ||
  body.astronaut_id !== request.astronaut_id
) {
  return fail(
    502,
    "IDENTITY_MISMATCH",
    "The backend response does not match the requested incident."
  );
}

// Verify exact request ID
if (body.request_id !== request.request_id) {
  return fail(
    502,
    "REQUEST_ID_MISMATCH",
    "The backend response does not match the review request."
  );
}

// Verify requested action
if (body.action !== request.action) {
  return fail(
    502,
    "ACTION_MISMATCH",
    "The backend response does not match the requested action."
  );
}

// Verify medical reviewer identity
if (body.actor !== request.reviewer_id) {
  return fail(
    502,
    "REVIEWER_MISMATCH",
    "The backend response does not match the requested medical reviewer."
  );
}

// Expected medical review statuses
// Aligned with the actual backend API contract.
const expectedStatus = {
  ACKNOWLEDGE: "ACKNOWLEDGED",
  START_REVIEW: "IN_REVIEW",
  COMPLETE_REVIEW: "REVIEW_COMPLETED"
};

// Expected previous status for each action
const expectedPreviousStatus = {
  ACKNOWLEDGE: "PENDING_MEDICAL_REVIEW",
  START_REVIEW: "ACKNOWLEDGED",
  COMPLETE_REVIEW: "IN_REVIEW"
};

// Validate action status transition
if (
  typeof body.previous_status !== "string" ||
  !body.previous_status.trim() ||
  body.new_status !== expectedStatus[request.action]
) {
  return fail(
    502,
    "STATUS_MISMATCH",
    "The returned incident status does not match the requested action."
  );
}

// Verify previous incident status
if (
  body.previous_status !== expectedPreviousStatus[request.action]
) {
  return fail(
    502,
    "PREVIOUS_STATUS_MISMATCH",
    "The previous incident status does not match the expected transition."
  );
}

// Verify status consistency
if (
  body.status !== undefined &&
  body.status !== body.new_status
) {
  return fail(
    502,
    "INCONSISTENT_STATUS",
    "The backend returned inconsistent incident statuses."
  );
}

// Verify backend confirmed persistence
if (body.persisted !== true) {
  return fail(
    502,
    "UPDATE_NOT_CONFIRMED",
    "The backend did not confirm the incident update."
  );
}

// Validate backend action timestamp
const actionTimestamp =
  body.created_at ?? body.updated_at ?? null;

if (
  typeof actionTimestamp !== "string" ||
  !Number.isFinite(Date.parse(actionTimestamp))
) {
  return fail(
    502,
    "INVALID_ACTION_TIMESTAMP",
    "The backend did not return a valid action timestamp."
  );
}

// Build successful acknowledgment
return [{
  json: {
    accepted: true,
    schema_version: "1.0",
    request_id: request.request_id,
    incident_id: request.incident_id,
    astronaut_id: request.astronaut_id,
    action: request.action,
    reviewer_id: body.actor,
    previous_status: body.previous_status,
    new_status: body.new_status,
    persisted: true,
    status: body.new_status,
    updated: true,
    updated_at: actionTimestamp,
    http_status: 200
  }
}];

